  && pre.AttackStatusRx == post.AttackStatusRx
  && pre.malformedCount == post.malformedCount
  && pre.EthernetFramesTxOut == post.EthernetFramesTxOut
  && pre.AttackStatusTx == post.AttackStatusTx
  && pre.CurrentMode == post.CurrentMode
  && pre.currentMode == post.currentMode
